// Builds two generated SQL files from the course content. Do not edit those files by hand.
//   sql/run_all_in_this_window.sql : sql/01 to sql/04 in one file (the practice-session build)
//   sql/99_check_all_queries.sql   : the build, then every query on the site, one batch each
// Usage (from the repo root): node tools/gen_check_script.js .
global.window = {};
const fs = require("fs"), path = require("path"), root = path.resolve(process.argv[2] || ".");
require(path.join(root, "assets/lessons.js")); require(path.join(root, "assets/scenarios.js"));

const parts = ["01_reference.sql", "02_silver.sql", "03_gold.sql", "04_dq_tests.sql"];
const build = parts.map(f => `/* ######################## sql/${f} ######################## */\n` +
  fs.readFileSync(path.join(root, "sql", f), "utf8").trim()).join("\n\n");

fs.writeFileSync(path.join(root, "sql/run_all_in_this_window.sql"),
`/* =====================================================================
   run_all_in_this_window.sql  -  ED SQL practice-session build
   GENERATED from sql/01 to sql/04 by tools/gen_check_script.js. Do not edit by hand.
   No permissions needed: it creates temporary tables (#name) only.
   1. Open a new query window on the database that holds dbo.ED_sandpit.
   2. Run this whole file (F5). It takes about 10 seconds.
   3. Do the lessons in the SAME window. Temp tables are deleted when you close it.
   ===================================================================== */

${build}
`);

const out = [];
const q = s => s.replace(/'/g, "''");
out.push(`/* =====================================================================
   99_check_all_queries.sql  -  runs the build, then every query on the site.
   GENERATED by tools/gen_check_script.js. Do not edit by hand.
   No permissions needed. Run the whole file in a NEW query window on the
   database that holds dbo.ED_sandpit.
   How to read it:
     - Messages tab: one "== ..." line per query, with the expected answer.
     - A red "Msg ..." line under a "== ..." line means that query failed.
     - Results tab: compare each result with the expected answer.
   ===================================================================== */

${build}`);
const add = (label, expect, sql) =>
  out.push(`PRINT '== ${q(label)}${expect !== undefined ? "  | expected: " + q(String(expect)) : ""}';\n${sql.trim()}\nGO`);
window.LESSONS.forEach((l, i) => {
  add(`Lesson ${i + 1} (${l.title}) - lesson query`, undefined, l.sql);
  l.drills.forEach(d => d.sql && add(`Lesson ${i + 1} drill ${d.id}`, d.ans, d.sql));
});
window.SCENARIOS.forEach((s, i) => {
  const run = s.drills.find(d => d.ans !== undefined && !d.sql);
  add(`Think ${i + 1} (${s.title}) - scenario query`, run ? run.ans : undefined, s.sql);
  s.drills.forEach(d => d.sql && add(`Think ${i + 1} drill ${d.id}`, d.ans, d.sql));
});
out.push(`PRINT '== Done. Check the Messages tab for red Msg lines.';\nGO\n`);
fs.writeFileSync(path.join(root, "sql/99_check_all_queries.sql"), out.join("\n\n"));

/* ---------- sql/98_check_answers.sql: one PASS/FAIL row per drill ---------- */
const nq = s => "N'" + s.replace(/'/g, "''") + "'";
const checks = [];
window.LESSONS.forEach((l, i) => l.drills.forEach(d => d.ans !== undefined && checks.push([`Lesson ${i + 1}`, d])));
window.SCENARIOS.forEach((s, i) => s.drills.forEach(d => d.ans !== undefined && checks.push([`Think ${i + 1}`, d])));
const missing = checks.filter(([, d]) => !d.sql).map(([, d]) => d.id);
if (missing.length) throw new Error("Checkable drills with no answer query: " + missing.join(", "));
const rows = checks.map(([where, d], n) => {
  const num = typeof d.ans === "number";
  const accept = [String(d.ans)].concat(d.accept || []).map(a => a.toLowerCase());
  return `-- ${d.id} (${where})
SET @n = ${n + 1}; SET @id = '${d.id}'; SET @where = '${where}';
SET @expected = ${nq(String(d.ans))}; SET @tol = ${num ? (d.tol || 0) : "NULL"}; SET @is_number = ${num ? 1 : 0};
SET @accept = ${nq("|" + accept.join("|") + "|")};
SET @sql = ${nq(d.sql.trim())};
DELETE FROM #got;
BEGIN TRY
    INSERT #got (v) EXEC (@sql);
    SELECT @rows = COUNT(*), @v = MAX(LTRIM(RTRIM(v))) FROM #got;
    SET @ok = CASE WHEN @rows <> 1 THEN 0
                   WHEN @is_number = 1 THEN IIF(ABS(TRY_CONVERT(DECIMAL(18,4), @v) - CAST(@expected AS DECIMAL(18,4))) <= @tol, 1, 0)
                   ELSE IIF(CHARINDEX('|' + LOWER(@v) + '|', @accept) > 0, 1, 0) END;
    INSERT #answer_check VALUES (@n, @id, @where, @expected, @v, @rows, IIF(@ok = 1, 'PASS', 'FAIL'),
        IIF(@rows <> 1, CONCAT('The query returned ', @rows, ' rows, not 1.'), NULL));
END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
    INSERT #answer_check VALUES (@n, @id, @where, @expected, NULL, NULL, 'ERROR', CONCAT('Msg ', ERROR_NUMBER(), ': ', ERROR_MESSAGE()));
END CATCH;`;
});
fs.writeFileSync(path.join(root, "sql/98_check_answers.sql"),
`/* =====================================================================
   98_check_answers.sql  -  checks the stored answer of every drill
   GENERATED by tools/gen_check_script.js. Do not edit by hand.
   No permissions needed: temp tables only.

   1. Open a NEW query window on the database that holds dbo.ED_sandpit.
   2. Run this whole file (F5). It builds the practice tables first.
   3. The last two results are the report: one row per drill with
      expected, got and PASS / FAIL / ERROR, then a count of each.
      To share it: click the grid, Ctrl+A, then right-click > Copy with Headers.
      It holds counts and percentages only. No patient data.
   ===================================================================== */

${build}

/* ######################## answer check ######################## */
SET NOCOUNT ON;
DROP TABLE IF EXISTS #got;
DROP TABLE IF EXISTS #answer_check;
CREATE TABLE #got (v NVARCHAR(400) NULL);
CREATE TABLE #answer_check (
    n INT, drill_id VARCHAR(20), drill_where VARCHAR(20),
    expected NVARCHAR(400), got NVARCHAR(400), rows_returned INT,
    result VARCHAR(10), error_message NVARCHAR(2000)
);
GO

DECLARE @n INT, @id VARCHAR(20), @where VARCHAR(20), @expected NVARCHAR(400), @tol DECIMAL(18,4),
        @is_number BIT, @accept NVARCHAR(1000), @sql NVARCHAR(MAX),
        @rows INT, @v NVARCHAR(400), @ok BIT;

${rows.join("\n\n")}
GO

SET NOCOUNT OFF;
SELECT n, drill_id, drill_where, expected, got, rows_returned, result, error_message
FROM #answer_check
ORDER BY n;

SELECT result, COUNT(*) AS drills
FROM #answer_check
GROUP BY result;
GO
`);
console.log("run_all parts:", parts.length, " check batches:", out.length, " answer checks:", checks.length);
